"""Matched real household service and migration forecasts across liquidity bands."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import hashlib,json
source=(ROOT/'assets/game.js').read_text();probe=r'''
window.__serviceAudit=(seed,scenario)=>{__townTest.reset(scenario,seed);G.policy.educationBudget=0;G.policy.defenseBudget=0;G.policy.serviceVoucherBudget=100;const school=seekPrivateServiceInvestment('school');__townTest.step(120);const fire=seekPrivateServiceInvestment('fire');__townTest.step(120);const all=G.households.filter(h=>h.people.length),sorted=all.slice().sort((a,b)=>migrationSpendable(a).spendable-migrationSpendable(b).spendable),sample=[sorted[0],sorted[Math.floor((sorted.length-1)/2)],sorted[sorted.length-1]],before=totalMoney(),offers=sample.map(h=>{const home=readBuild(h.home),services=migrationServiceAt(home),fireActual=privateFireResponse(home),assessment=migrationAssessment(home,[{age:12,skill:.5,health:90}],2500);return {band:h===sample[0]?'low':h===sample[1]?'middle':'high',cash:h.cash,spendable:migrationSpendable(h).spendable,fees:h.privateServiceFees||0,publicSchool:localCivicCoverage('school',h.id),publicServiceForecast:services,realizedPrivateSchool:G.privateServiceProvision?.school?.[h.id]||0,schoolCapacity:G.firms.filter(f=>f.privateService==='school'&&!f.closed&&f.serviceCapacity>0).reduce((n,f)=>n+Math.max(0,f.serviceCapacity-f.clientsToday),0),privateFire:fireActual,assessment:{eligible:assessment.eligible,reasons:assessment.reasons,services:assessment.services,budget:assessment.budget,schoolOffer:assessment.services.privateSchoolOffer||null}}});__townTest.step(1);const actual=sample.map(h=>({id:h.id,privateFees:h.privateServiceFees||0,privateReceipts:G.firms.filter(f=>f.privateService).reduce((n,f)=>n+(f.privateReceipts||0),0),voucherSpend:G.privateServiceProvision?.vouchers||0,coverage:{health:G.serviceProvision?.health?.coverage||0,school:G.serviceProvision?.school?.coverage||0},privateSchool:G.privateServiceProvision?.school?.[h.id]||0,fire:privateFireResponse(readBuild(h.home))}));const end=totalMoney(),saved=__townTest.save();__townTest.step(30);const replay=archivePayload();if(!hydrateSave(saved))throw Error('Save rejected');__townTest.step(30);if(archivePayload()!==replay)throw Error('Replay mismatch');return {seed,scenario,start:before,end,cashDrift:end-before,school,fire,offers,actual,valid:validateTown(),goods:goodsBalance(),migration:migrationDiagnostics()};};'''
rows=[]
with sync_playwright()as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_default_timeout(180000);errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click()
 for scenario in ['settlement','regional']:
  r=p.evaluate('o=>__serviceAudit(o.seed,o.scenario)',{'seed':42,'scenario':scenario});assert r['valid']['ok']and max(abs(x['error'])for x in r['goods'])<.001 and abs(r['cashDrift'])<.001;rows.append(r);print(scenario,'cashDrift',r['cashDrift'],'offers',[(x['band'],round(x['spendable']),x['assessment']['schoolOffer'])for x in r['offers']],flush=True)
 assert not errors;b.close()
(ROOT/'reports/service-access').mkdir(exist_ok=True);(ROOT/'reports/service-access/households.json').write_text(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'rows':rows,'errors':errors},indent=2));print('PASS actual liquidity bands, public coverage, private staffing/fees, migration forecasts, cash/goods and replay')
